import { useBlockProps, InspectorControls } from "@wordpress/block-editor";
import { PanelBody, TextControl, SelectControl, RangeControl, RadioControl, FormTokenField, ToggleControl } from "@wordpress/components";
import { useSelect } from "@wordpress/data";
import { useState } from "@wordpress/element";

export default function Edit({ attributes, setAttributes }) {
    const { mainTitle, subTitle, accentWord, selectionType, categoryId, productIds, customCategoryOrder, orderBy, limit, productGradients, globalSavingsPill, productSavingsPills } = attributes;
    const blockProps = useBlockProps();
    const [selectedProductId, setSelectedProductId] = useState(null);

    const predefinedGradients = {
        zloty: 'linear-gradient(177.46deg, #d28f33 23.78%, #c17627 9.03%, #f3ceaa 51.08%, #c17627 87.59%, #c99b70 132.32%, #b06b23 158.8%)',
        srebrny: 'linear-gradient(177.46deg, #999999 23.78%, #b2b2b2 35%, #f5f5f5 50%, #cccccc 75%, #999999 95%, #f5f5f5 110%)',
        platynowy: 'linear-gradient(177.46deg, #3a3a3a 23.78%, #606060 35%, #8f8f8f 50%, #cecece 75%, #888888 95%, #464646 110%)',
        rosegold: 'linear-gradient(105deg, #e9c1b9 0%, #bc8d80 26%, #8d6154 62%, #a6776a 84%, #cf9f8f 100%)'
    };

    const gradientOptions = [
        { label: 'Domyślny / Brak', value: 'none', background: '#e0e0e0' },
        { label: 'Złoty', value: 'zloty', background: predefinedGradients.zloty },
        { label: 'Srebrny', value: 'srebrny', background: predefinedGradients.srebrny },
        { label: 'Platynowy', value: 'platynowy', background: predefinedGradients.platynowy },
        { label: 'Rose Gold', value: 'rosegold', background: predefinedGradients.rosegold },
        { label: 'Własny CSS', value: 'custom', background: 'repeating-linear-gradient(45deg, #eee, #eee 10px, #ddd 10px, #ddd 20px)' },
    ];

    const categories = useSelect((select) => {
        return select("core").getEntityRecords("taxonomy", "product_cat", { per_page: -1 });
    }, []);

    const products = useSelect((select) => {
        // Fetch all published products with _embed to get images
        return select("core").getEntityRecords("postType", "product", { per_page: 100, status: "publish", _embed: true });
    }, []);

    const categoryOptions = [
        { label: "Wszystkie kategorie", value: "" },
        ...(categories || []).map((cat) => ({
            label: cat.name,
            value: cat.slug,
        })),
    ];

    const productSuggestions = (products || []).map(p => p.title.rendered);
    
    const handleProductChange = (selectedTitles) => {
        const newIds = selectedTitles.map(title => {
            const product = products.find(p => p.title.rendered === title);
            return product ? product.id : null;
        }).filter(id => id !== null);
        setAttributes({ productIds: newIds });
    };

    const selectedProductTitles = (productIds || []).map(id => {
        const product = (products || []).find(p => p.id === id);
        return product ? product.title.rendered : "";
    }).filter(title => title !== "");

    // Prepare preview products
    let previewProducts = [];
    if (selectionType === 'manual') {
        previewProducts = (productIds || []).map(id => {
            return (products || []).find(p => p.id === id);
        }).filter(Boolean);
    } else {
        // For category view
        if (orderBy === 'menu_order' && customCategoryOrder && customCategoryOrder.length > 0) {
            previewProducts = customCategoryOrder.map(id => {
                return (products || []).find(p => p.id === id);
            }).filter(Boolean);
        } else {
            const selectedCategory = (categories || []).find(cat => cat.slug === categoryId);
            const selectedCategoryId = selectedCategory ? selectedCategory.id : null;
            previewProducts = (products || []).filter(p => {
                if (!selectedCategoryId) return true;
                return p.categories && p.categories.includes(selectedCategoryId);
            }).slice(0, limit);
            
            // Fallback for WooCommerce products REST response if 'categories' isn't natively populated but 'product_cat' might be.
            if (previewProducts.length === 0 && selectedCategoryId) {
                previewProducts = (products || []).filter(p => {
                    // Czasami REST dla produktów WC przetrzymuje kategorie w innej strukturze.
                    // Spróbujmy znaleźć cokolwiek:
                    if (p.product_cat && p.product_cat.includes(selectedCategoryId)) return true;
                    return false; // W najgorszym razie podgląd nie pofiltruje dokładnie
                }).slice(0, limit);
            }
            
            // Jeżeli wciąż pusty (brak filtru), weź po prostu produkty.
            if (previewProducts.length === 0 && (products || []).length > 0) {
                 previewProducts = (products || []).slice(0, limit);
            }
        }
    }



    const handleMoveButton = (e, index, direction) => {
        e.stopPropagation();
        e.preventDefault();
        
        let newIds = [];
        if (selectionType === 'manual') {
            newIds = [...productIds];
        } else {
            newIds = customCategoryOrder && customCategoryOrder.length > 0 
                ? [...customCategoryOrder] 
                : previewProducts.map(p => p.id);
        }
        
        if (direction === 'left' && index > 0) {
            const temp = newIds[index - 1];
            newIds[index - 1] = newIds[index];
            newIds[index] = temp;
        } else if (direction === 'right' && index < newIds.length - 1) {
            const temp = newIds[index + 1];
            newIds[index + 1] = newIds[index];
            newIds[index] = temp;
        }
        
        if (selectionType === 'manual') {
            setAttributes({ productIds: newIds });
        } else {
            setAttributes({ customCategoryOrder: newIds });
        }
    };

    return (
        <div {...blockProps}>
            <InspectorControls>
                <PanelBody title="Ustawienia Siatki Produktów" initialOpen={true}>
                    <TextControl
                        label="Tytuł główny"
                        value={mainTitle}
                        onChange={(val) => setAttributes({ mainTitle: val })}
                    />
                    <TextControl
                        label="Podtytuł (Szary, marka)"
                        value={subTitle}
                        onChange={(val) => setAttributes({ subTitle: val })}
                    />
                    <TextControl
                        label="Słowo do akcentowania (Dolce font)"
                        value={accentWord}
                        onChange={(val) => setAttributes({ accentWord: val })}
                        help="Wpisz słowo występujące w tytule lub podtytule, które ma zostać wyróżnione fontem Dolce."
                    />

                    <RadioControl
                        label="Wybierz źródło produktów"
                        selected={selectionType}
                        options={[
                            { label: 'Kategoria', value: 'category' },
                            { label: 'Pojedyncze produkty (Ręcznie)', value: 'manual' },
                        ]}
                        onChange={(val) => setAttributes({ selectionType: val })}
                    />

                    {selectionType === 'category' && (
                        <SelectControl
                            label="Kategoria Produktów"
                            value={categoryId}
                            options={categoryOptions}
                            onChange={(val) => setAttributes({ categoryId: val, customCategoryOrder: [] })}
                        />
                    )}

                    {selectionType === 'manual' && (
                        <div style={{ marginBottom: "20px" }}>
                            <FormTokenField
                                label="Szukaj i dodaj produkty"
                                value={selectedProductTitles}
                                suggestions={productSuggestions}
                                onChange={handleProductChange}
                                __experimentalExpandOnFocus={true}
                            />
                            <p style={{ fontSize: "12px", color: "#666" }}>
                                Możesz zmieniać kolejność łapiąc i przeciągając produkty w podglądzie bloku!
                            </p>
                        </div>
                    )}

                    <SelectControl
                        label="Sortuj według"
                        value={orderBy}
                        options={[
                            { label: 'Ręcznie / Kolejność w Menu', value: 'menu_order' },
                            { label: 'Po dacie (Najnowsze)', value: 'date' },
                            { label: 'Po nazwie (A-Z)', value: 'title' },
                            { label: 'Po popularności (Bestsellery)', value: 'popularity' },
                        ]}
                        onChange={(val) => setAttributes({ orderBy: val })}
                    />

                    <RangeControl
                        label="Limit produktów do pokazania"
                        value={limit}
                        onChange={(val) => setAttributes({ limit: val })}
                        min={1}
                        max={24}
                    />

                    <ToggleControl
                        label="Włącz pill 'Oszczędzasz' dla całej siatki (jeśli w promocji)"
                        checked={globalSavingsPill}
                        onChange={(val) => setAttributes({ globalSavingsPill: val })}
                    />
                </PanelBody>

                {selectedProductId && (
                    <PanelBody title="Opcje zaznaczonego produktu" initialOpen={true}>
                        <p style={{fontSize: '13px', color: '#666', marginBottom: '15px'}}>
                            Wybrany produkt ID: <strong>{selectedProductId}</strong>
                        </p>
                        
                        <div style={{ marginBottom: '20px' }}>
                            <label style={{ display: 'block', fontSize: '13px', fontWeight: 500, marginBottom: '10px' }}>
                                Wizualny wybór gradientu u góry karty
                            </label>
                            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '10px' }}>
                                {gradientOptions.map(opt => {
                                    const currentVal = (productGradients || {})[selectedProductId]?.type || 'none';
                                    const isSelected = currentVal === opt.value || (currentVal === '' && opt.value === 'none');
                                    
                                    return (
                                        <div 
                                            key={opt.value}
                                            onClick={() => {
                                                const newGradients = { ...(productGradients || {}) };
                                                if (opt.value === 'none') {
                                                    delete newGradients[selectedProductId];
                                                } else {
                                                    newGradients[selectedProductId] = { 
                                                        type: opt.value, 
                                                        customValue: newGradients[selectedProductId]?.customValue || '' 
                                                    };
                                                }
                                                setAttributes({ productGradients: newGradients });
                                            }}
                                            style={{
                                                cursor: 'pointer',
                                                border: isSelected ? '2px solid #007cba' : '2px solid transparent',
                                                borderRadius: '8px',
                                                padding: '4px',
                                                textAlign: 'center',
                                                transition: 'all 0.2s',
                                                backgroundColor: isSelected ? '#f0f8ff' : '#fff'
                                            }}
                                        >
                                            <div style={{
                                                height: '24px',
                                                borderRadius: '4px',
                                                background: opt.background,
                                                marginBottom: '6px',
                                                boxShadow: 'inset 0 0 0 1px rgba(0,0,0,0.1)'
                                            }}></div>
                                            <span style={{ fontSize: '11px', display: 'block', lineHeight: 1.2 }}>{opt.label}</span>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>

                        {(productGradients || {})[selectedProductId]?.type === 'custom' && (
                            <TextControl
                                label="Własny kod CSS gradientu"
                                help="Np. linear-gradient(90deg, red, blue)"
                                value={(productGradients || {})[selectedProductId]?.customValue || ''}
                                onChange={(val) => {
                                    const newGradients = { ...(productGradients || {}) };
                                    if (newGradients[selectedProductId]) {
                                        newGradients[selectedProductId].customValue = val;
                                        setAttributes({ productGradients: newGradients });
                                    }
                                }}
                            />
                        )}

                        <ToggleControl
                            label="Włącz pill 'Oszczędzasz' dla tego produktu (jeśli w promocji)"
                            checked={!!(productSavingsPills || {})[selectedProductId]}
                            onChange={(val) => {
                                const newPills = { ...(productSavingsPills || {}) };
                                newPills[selectedProductId] = val;
                                setAttributes({ productSavingsPills: newPills });
                            }}
                        />
                    </PanelBody>
                )}
            </InspectorControls>

            <div style={{ padding: "30px", border: "1px solid #e0e0e0", borderRadius: "10px", backgroundColor: "#fff", boxShadow: "inset 0 0 20px rgba(0,0,0,0.02)" }}>
                <h3 style={{ margin: "0 0 20px 0", fontSize: "24px" }}>
                    <span style={{ color: "#111", fontWeight: "800" }}>{mainTitle} </span>
                    <span style={{ color: "#888", fontWeight: "400" }}>{subTitle}</span>
                </h3>
                
                <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(200px, 1fr))", gap: "20px" }}>
                    {previewProducts.length === 0 ? (
                        <p style={{ gridColumn: "1 / -1", color: "#999", textAlign: "center", padding: "40px" }}>
                            {products === null ? "Ładowanie produktów..." : "Brak produktów do wyświetlenia. Dodaj produkty w panelu bocznym."}
                        </p>
                    ) : (
                        previewProducts.map((product, index) => {
                            const isManual = orderBy === 'menu_order';
                            const imageUrl = product._embedded?.['wp:featuredmedia']?.[0]?.source_url || "";
                            
                            const prodGrad = (productGradients || {})[product.id];
                            let activeGradientCSS = null;
                            if (prodGrad && prodGrad.type !== 'none') {
                                if (prodGrad.type === 'custom' && prodGrad.customValue) {
                                    activeGradientCSS = prodGrad.customValue;
                                } else if (predefinedGradients[prodGrad.type]) {
                                    activeGradientCSS = predefinedGradients[prodGrad.type];
                                }
                            }
                            
                            return (
                                <div 
                                    key={product.id + '-' + index}
                                    onClick={() => setSelectedProductId(product.id)}
                                    style={{ 
                                        backgroundColor: "#fff", 
                                        borderRadius: "12px", 
                                        overflow: "hidden", 
                                        boxShadow: "0 4px 10px rgba(0,0,0,0.05)",
                                        border: selectedProductId === product.id ? "2px solid #007cba" : "2px solid transparent",
                                        transition: "all 0.2s ease",
                                        display: "flex",
                                        flexDirection: "column",
                                        height: "100%",
                                        cursor: "pointer",
                                        position: "relative"
                                    }}
                                >
                                    {activeGradientCSS && (
                                        <div style={{
                                            position: "absolute",
                                            top: 0,
                                            left: 0,
                                            right: 0,
                                            height: "16px",
                                            background: activeGradientCSS,
                                            zIndex: 2
                                        }}></div>
                                    )}
                                    <div style={{ 
                                        height: "200px", 
                                        backgroundColor: "#f5f5f5", 
                                        backgroundImage: imageUrl ? `url(${imageUrl})` : "none", 
                                        backgroundSize: "cover", 
                                        backgroundPosition: "center",
                                        display: "flex",
                                        alignItems: "center",
                                        justifyContent: "center",
                                        flexShrink: 0
                                    }}>
                                        {!imageUrl && <span style={{color: "#aaa"}}>Brak zdjęcia</span>}
                                    </div>
                                    <div style={{ padding: "15px", fontSize: "14px", fontWeight: "600", textAlign: "center", color: "#333", lineHeight: "1.3", flexGrow: 1 }} dangerouslySetInnerHTML={{ __html: product.title.rendered }} />
                                    
                                    {isManual && (
                                        <div style={{ display: "flex", justifyContent: "space-between", padding: "10px", backgroundColor: "#f9f9f9", borderTop: "1px solid #eee", marginTop: "auto" }}>
                                            <button 
                                                onClick={(e) => handleMoveButton(e, index, 'left')}
                                                disabled={index === 0}
                                                style={{ cursor: index === 0 ? "not-allowed" : "pointer", padding: "5px 10px", border: "1px solid #ccc", borderRadius: "4px", background: "#fff", opacity: index === 0 ? 0.3 : 1 }}
                                                title="Przesuń w lewo"
                                            >
                                                ◀
                                            </button>
                                            <button 
                                                onClick={(e) => handleMoveButton(e, index, 'right')}
                                                disabled={index === previewProducts.length - 1}
                                                style={{ cursor: index === previewProducts.length - 1 ? "not-allowed" : "pointer", padding: "5px 10px", border: "1px solid #ccc", borderRadius: "4px", background: "#fff", opacity: index === previewProducts.length - 1 ? 0.3 : 1 }}
                                                title="Przesuń w prawo"
                                            >
                                                ▶
                                            </button>
                                        </div>
                                    )}
                                </div>
                            );
                        })
                    )}
                </div>
                
                {orderBy === 'menu_order' && (
                    <div style={{ textAlign: "center", marginTop: "25px", padding: "10px", backgroundColor: "#f0f8ff", borderRadius: "8px", color: "#007cba", fontSize: "14px", fontWeight: "bold" }}>
                        <span style={{marginRight: "8px"}}>👆</span>
                        Użyj strzałek na kafelkach, aby zmienić ich kolejność
                    </div>
                )}
            </div>
        </div>
    );
}
